def longest_regular_bracket_subsequence(s):
    n = len(s)
    max_length = 0
    count = 0
    stack = [-1]  # Initialize stack with -1 to handle the base case

    for i in range(n):
        if s[i] == '(':
            stack.append(i)
        else:
            if len(stack) > 1:
                stack.pop()
                start = stack[-1]
                length = i - start
                if length > max_length:
                    max_length = length
                    count = 1
                elif length == max_length:
                    count += 1
            else:
                stack[0] = i

    if max_length == 0:
        return "0 1"
    else:
        return f"{max_length} {count}"

